def transform(grid):
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[i][j] == 2 for i in (r, r + 1) for j in (c, c + 1)):
                blocks.append((r, c))

    # Alternate from right to left, recoloring the rightmost block first.
    out = [row[:] for row in grid]
    for idx, (r, c) in enumerate(sorted(blocks, key=lambda p: p[1], reverse=True)):
        if idx % 2 == 0:
            for i in (r, r + 1):
                for j in (c, c + 1):
                    out[i][j] = 8
    return out
